	static long countTermKind(long[] ids, int expectedKind) {
		long count = 0L;
		int upperBound = SPECIES.loopBound(ids.length);
		int i = 0;
		for (; i < upperBound; i += SPECIES.length()) {
			LongVector lanes = LongVector.fromArray(SPECIES, ids, i);
			LongVector types = lanes.lanewise(VectorOperators.LSHR, 1).and(0x3fL);
			var odd = lanes.and(1L).compare(VectorOperators.NE, 0L);
			var matches = switch (expectedKind) {
			case 1 -> odd.not().and(types.compare(VectorOperators.EQ, 1L));
			case 2 -> odd.or(types.compare(VectorOperators.EQ, 2L))
					.or(types.compare(VectorOperators.EQ, 5L))
					.or(types.compare(VectorOperators.GE, 16L));
			case 3 -> odd.not().and(types.compare(VectorOperators.EQ, 3L));
			case 4 -> odd.not().and(types.compare(VectorOperators.EQ, 4L));
			case 5 -> odd.not().and(types.compare(VectorOperators.EQ, 0L));
			default -> odd.not()
					.and(types.compare(VectorOperators.GT, 5L))
					.and(types.compare(VectorOperators.LT, 16L));
			};
			count += matches.trueCount();
		}
		for (; i < ids.length; i++) {
			count += scalarTermKind(ids[i]) == expectedKind ? 1L : 0L;
		}
		return count;
	}

	static long classifyColumnTraits(long[] ids) {
		if (ids.length == 0) {
			return 0L;
		}
		int firstKind = scalarTermKind(ids[0]);
		int sameKindCount = 0;
		int literalCount = 0;
		int legacyLiteralCount = 0;
		int upperBound = SPECIES.loopBound(ids.length);
		int i = 0;
		for (; i < upperBound; i += SPECIES.length()) {
			LongVector lanes = LongVector.fromArray(SPECIES, ids, i);
			LongVector types = lanes.lanewise(VectorOperators.LSHR, 1).and(0x3fL);
			var odd = lanes.and(1L).compare(VectorOperators.NE, 0L);
			var literal = odd.or(types.compare(VectorOperators.EQ, 2L))
					.or(types.compare(VectorOperators.EQ, 5L))
					.or(types.compare(VectorOperators.GE, 16L));
			var sameKind = switch (firstKind) {
			case 1 -> odd.not().and(types.compare(VectorOperators.EQ, 1L));
			case 2 -> literal;
			case 3 -> odd.not().and(types.compare(VectorOperators.EQ, 3L));
			case 4 -> odd.not().and(types.compare(VectorOperators.EQ, 4L));
			case 5 -> odd.not().and(types.compare(VectorOperators.EQ, 0L));
			default -> odd.not()
					.and(types.compare(VectorOperators.GT, 5L))
					.and(types.compare(VectorOperators.LT, 16L));
			};
			sameKindCount += sameKind.trueCount();
			literalCount += literal.trueCount();
			legacyLiteralCount += odd.not().and(types.compare(VectorOperators.EQ, 2L)).trueCount();
		}
		for (; i < ids.length; i++) {
			long id = ids[i];
			int kind = scalarTermKind(id);
			sameKindCount += kind == firstKind ? 1 : 0;
			literalCount += kind == 2 ? 1 : 0;
			legacyLiteralCount += kind == 2 && (id & 1L) == 0L && (id >>> 1 & 0x3fL) == 2L ? 1 : 0;
		}
		return packTraits(firstKind, sameKindCount == ids.length, literalCount, legacyLiteralCount);
	}

	static long saturatedMultiplicitySum(long[] multiplicities) {
		if (SPECIES.length() != 2) {
			return ScalarAdjacencyKernelBenchmark.saturatedMultiplicitySum(multiplicities);
		}
		long sum = 0L;
		int upperBound = SPECIES.loopBound(multiplicities.length);
		int i = 0;
		for (; i < upperBound; i += SPECIES.length()) {
			long pair = LongVector.fromArray(SPECIES, multiplicities, i).reduceLanes(VectorOperators.ADD);
			if (pair < 0L) {
				return Long.MAX_VALUE;
			}
			sum = saturatedAdd(sum, pair);
			if (sum == Long.MAX_VALUE) {
				return sum;
			}
		}
		for (; i < multiplicities.length; i++) {
			sum = saturatedAdd(sum, multiplicities[i]);
		}
		return sum;
	}

	static boolean orderedUnique(long[] values, boolean strict) {
		int comparisons = values.length - 1;
		int upperBound = SPECIES.loopBound(comparisons);
		int i = 0;
		for (; i < upperBound; i += SPECIES.length()) {
			LongVector previous = LongVector.fromArray(SPECIES, values, i);
			LongVector current = LongVector.fromArray(SPECIES, values, i + 1);
			var ordered = strict ? previous.compare(VectorOperators.ULT, current)
					: previous.compare(VectorOperators.ULE, current);
			if (!ordered.allTrue()) {
				return false;
			}
		}
		for (; i < comparisons; i++) {
			int comparison = Long.compareUnsigned(values[i], values[i + 1]);
			if (strict ? comparison >= 0 : comparison > 0) {
				return false;
			}
		}
		return true;
	}

	static boolean uniformCoreLiteralDatatype(long[] ids) {
		if (ids.length == 0) {
			return false;
		}
		long expectedTag = ids[0] >>> 7 & 0x3fL;
		int upperBound = SPECIES.loopBound(ids.length);
		int i = 0;
		for (; i < upperBound; i += SPECIES.length()) {
			LongVector lanes = LongVector.fromArray(SPECIES, ids, i);
			var coreLiteral = lanes.and(1L)
					.compare(VectorOperators.EQ, 0L)
					.and(lanes.lanewise(VectorOperators.LSHR, 1)
							.and(0x3fL)
							.compare(VectorOperators.EQ, 5L))
					.and(lanes.lanewise(VectorOperators.LSHR, 7)
							.and(0x3fL)
							.compare(VectorOperators.EQ, expectedTag));
			if (!coreLiteral.allTrue()) {
				return false;
			}
		}
		for (; i < ids.length; i++) {
			long id = ids[i];
			if ((id & 1L) != 0L || (id >>> 1 & 0x3fL) != 5L || (id >>> 7 & 0x3fL) != expectedTag) {
				return false;
			}
		}
		return true;
	}

	static long decodeUnsignedBytes(byte[] source, long base, long[] target) {
		int sourceWidth = BYTE_SPECIES.length();
		int outputWidth = SPECIES.length();
		int upperBound = source.length - source.length % sourceWidth;
		int i = 0;
		for (; i < upperBound; i += sourceWidth) {
			ByteVector packed = ByteVector.fromArray(BYTE_SPECIES, source, i);
			for (int part = 0; part < sourceWidth / outputWidth; part++) {
				LongVector decoded = (LongVector) packed.convertShape(VectorOperators.ZERO_EXTEND_B2L, SPECIES, part);
				decoded.add(base).intoArray(target, i + part * outputWidth);
			}
		}
		for (; i < source.length; i++) {
			target[i] = base + Byte.toUnsignedLong(source[i]);
		}
		return target.length == 0 ? 0L : target[target.length - 1];
	}

